STATUS=P['status_labels']
def value(x,k=''):
 if x is None:return '<span class="unknown">Inconnu / non applicable selon le champ</span>'
 if isinstance(x,bool):
  if k.endswith(('verified','validated','acquired','complete','received')): return 'Vérifié dans le périmètre déclaré' if x else '<span class="unknown">Non vérifié — preuve non obtenue</span>'
  return 'Oui' if x else 'Non'
 if isinstance(x,(int,float)):
  if k in ('basis_eur','enterprise_low_ht','enterprise_high_ht','investors_fees_added_ttc'):return f'{x:,.2f}'.replace(',', ' ').replace('.', ',')+' EUR'
  return E(x)
 if isinstance(x,str):
  if x in STATUS:return '<span class="badge">'+STATUS[x]+'</span>'
  if x.startswith('https://'):return '<a href="'+E(x)+'" rel="noreferrer">'+E(x)+'</a>'
  if k in ('source_document','document') and (ROOT/x).exists():return '<a href="../'+E(x)+'">'+E(x)+'</a>'
  if k=='local_reference':
   p=x.removeprefix('../')
   return '<a href="../'+E(p)+'">'+E(x)+'</a>' if (ROOT/p).exists() else E(x)
  return E(x)
 if isinstance(x,list):
  if not x:return '<span class="unknown">Aucun élément renseigné</span>'
  if k in ('sources','source_ids') and all(isinstance(s,str) for s in x):return ' · '.join('<a href="sources.html#'+E(s)+'">'+E(s)+'</a>' for s in x)
  return '<ul>'+''.join('<li>'+value(v,k)+'</li>' for v in x)+'</ul>'
 if isinstance(x,dict):
  return '<dl>'+''.join('<div><dt>'+E(labels.get(a,a.replace('_',' ')))+'</dt><dd>'+value(b,a)+'</dd></div>' for a,b in x.items())+'</dl>'
 return E(x)
def details(title,x):return '<details><summary>'+E(title)+'</summary>'+value(x)+'</details>'
def record(x,subtitle='',group='',extra=''):
 name=x.get('name',x.get('title',x.get('id','Fiche')))
 return '<article class="card record" id="'+E(x['id'])+'" data-group="'+E(group)+'"><div class="eyebrow">'+E(x['id'])+' · '+E(subtitle)+'</div><h2>'+E(name)+'</h2>'+extra+details('Consulter la fiche complète', {k:v for k,v in x.items() if k not in ['id','name']})+'</article>'
def filters(kind,options,export):
 return '<div class="toolbar interactive" hidden><label>Rechercher<input type="search" id="search" placeholder="Nom, activité, pays, risque…"></label><label>'+E(kind)+'<select id="group"><option value="">Tout afficher</option>'+''.join('<option value="'+E(a)+'">'+E(b)+'</option>' for a,b in options)+'</select></label><button type="button" id="export-records" data-export="'+export+'">Exporter les fiches affichées (JSON)</button><p id="count" role="status"></p></div>'
def docs(files):
 out=''
 for p in files:
  raw=subprocess.check_output(['pandoc','--from=gfm','--to=html5','--shift-heading-level-by=2',str(ROOT/p)],text=True)
  raw=re.sub(r'href="(?!https?://|#)([^\"]+)"',lambda m:'href="../'+m[1]+'"',raw)
  out+='<details class="document"><summary>'+E(p.replace('.md','').replace('_',' '))+' — texte intégral daté</summary><p class="muted">Document historique. L’état courant du programme figure en tête de cette page ; les faits restent datés.</p>'+raw+'</details>'
 return out
NAV=[('index','Synthèse'),('niches','Domaines'),('entreprises','Entreprises'),('investisseurs','Accès investisseurs'),('simulateur','Simulateur'),('parcours','Fonctionnement'),('sources','Sources')]
def page(key,title,desc,body,scripts=''):
 nav=''.join('<a '+('aria-current="page" ' if key==k else '')+'href="'+k+'.html">'+n+'</a>' for k,n in NAV)
 s='<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+E(desc)+'"><title>'+E(title)+' — ETHIGONE</title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/donnees-et-moteurs.js"></script><script defer src="assets/app.js"></script>'+scripts+'</head><body data-page="'+key+'"><a class="skip" href="#contenu">Aller au contenu</a><header><a class="brand" href="index.html">ETHIGONE <span>Étude du modèle 3</span></a><div class="edition">Dossier de décision · 18 novembre 2026<br>Recherche et simulations, aucune offre d’investissement</div></header><nav aria-label="Rubriques">'+nav+'</nav><main id="contenu"><div class="page-heading"><p class="eyebrow">Dossier documentaire · J8</p><h1>'+E(title)+'</h1><p class="lead">'+E(desc)+'</p></div><noscript><p class="callout">Lecture complète disponible sans JavaScript. Les filtres, exports et simulations modifiables nécessitent JavaScript ; les références de base restent lisibles.</p></noscript>'+body+'</main><footer><p>Modèle 3 décidé · aucune niche adoptée · aucune validation commerciale, juridique ou charia acquise.</p><p>Documents et moteurs locaux. Les liens externes nécessitent internet et s’ouvrent seulement sur votre clic. Sources consultées entre le 11 et le 16 novembre 2026, sans actualisation web à J8.</p><button class="interactive" hidden type="button" id="print">Imprimer / enregistrer en PDF</button> <a href="LISEZ-MOI.md">Mode d’emploi</a></footer></body></html>'
 (OUT/(key+'.html')).write_text(s)

body='''<section class="hero"><div><p class="eyebrow">L’essentiel en une minute</p><h2>Une piste à tester.<br>Pas encore un modèle rentable validé.</h2><p>Examiner d’abord les <strong>emballages professionnels en réassort, achetés et revendus sur commande ferme</strong>. La filtration non critique est le repli ; les PC reconditionnés restent en réserve.</p><p>ETHIGONE proposerait de préparer et suivre les opérations. Il reste à prouver un besoin réel, une volonté de payer et une voie d’accès aux investisseurs compatible.</p><a class="button" href="simulateur.html">Comprendre l’économie</a> <a href="entreprises.html">Voir les entreprises repérées →</a></div><aside><span class="badge">PROPOSITION J6</span><h3>Le test décisif</h3><p>Reconstituer une vraie commande, ses coûts et ses dates de paiement. Comparer l’acompte client, le crédit fournisseur et l’accès direct à une plateforme.</p><p><strong>Si ces solutions couvrent déjà le besoin, financer le lot via ETHIGONE peut être inutile.</strong></p></aside></section>
<section class="grid stats" aria-label="Étendue du travail"><div class="card"><strong>6</strong><p>domaines comparés</p></div><div class="card"><strong>17</strong><p>entreprises repérées, aucun besoin confirmé</p></div><div class="card"><strong>10</strong><p>points d’entrée, aucun partenariat acquis</p></div><div class="card"><strong>3</strong><p>opérations anonymisées simulées</p></div></section>
<h2>Ce qui est décidé, proposé et encore à prouver</h2><div class="grid"><article class="card"><span class="badge">DÉCIDÉ</span><h3>Le modèle 3</h3><p>Des entreprises et opérations ciblées, accessibles à des particuliers éligibles, notamment détenteurs de stablecoins. Charia indispensable ; import/export facultatif.</p></article><article class="card"><span class="badge">PROPOSITION</span><h3>Un service de préparation et suivi</h3><p>Documenter commandes, coûts, propriété et encaissements. Facturer un travail utile et permis, avec un payeur et un mandat à définir.</p></article><article class="card"><span class="badge">À VÉRIFIER</span><h3>Le passage à une vraie opération</h3><p>Besoin payant, coûts complets, distribution, contrats, fiscalité, charia et chaîne de paiement. Aucun pays, véhicule ou circuit stablecoin adopté.</p></article></div>
<h2>Pourquoi le ticket ne résout pas tout</h2><p>Tous les chiffres ci-dessous sont des <strong>HYPOTHÈSES</strong> pour O2, par opération, avant impôt. Ils ne décrivent aucune entreprise repérée.</p><div class="table-wrap"><table><caption>Résultat ETHIGONE — emballages O2</caption><thead><tr><th>Variante</th><th>Résultat</th></tr></thead><tbody><tr><td>Base publiée : ticket indicatif 500 €, 6 opérations/mois</td><td>−1 121,25 €</td></tr><tr><td>Ticket indicatif 2 500 €, 6 opérations/mois</td><td>+633,75 €</td></tr><tr><td>Ticket 2 500 €, 3 opérations/mois et 20 % de dossiers acceptés</td><td>−335,00 €</td></tr></tbody></table></div><p>Le bénéfice du lot est distinct du résultat d’ETHIGONE. Le ticket indicatif sert au calcul du nombre de participants ; ce n’est pas un minimum adopté. <a href="simulateur.html">Modifier et vérifier les hypothèses →</a></p>
<h2>Accès aux investisseurs</h2><p><strong>EthisX</strong> : porte à instruire pour un lot commercial, sous conditions de pays, instrument et coûts. <strong>Lita</strong> : actions d’entreprise, pas équivalent à un lot court. <strong>Centrifuge</strong> : infrastructure à étudier, sans distributeur ni capitaux acquis. <a href="investisseurs.html">Comparer les accès →</a></p>
<h2>Étape suivante, hors de ce programme</h2><p>Après une autorisation distincte de contact : confronter la proposition à un dossier réel et à la réponse écrite d’un distributeur, puis recalculer avec les pièces et devis. Aucune collecte ni intégration financière n’est justifiée aujourd’hui.</p>
<section class="callout"><h2>Programme documentaire livré</h2><p>J1 à J6 : recherche, simulations, parcours et recommandation. J7 : cohérence et préparation. J8 : dossier HTML hors ligne. La fin du programme est le <strong>18 novembre 2026</strong> ; aucun prochain lot automatique.</p><p>La contre-revue J6 a été réalisée par le coordinateur seul. Les contrôles de calcul et de présentation ne remplacent aucun avis professionnel.</p></section><h2>Lire les conclusions en détail</h2>'''
